<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Questions · UIU Recruitment Portal Admin</title><?php $adminSection='questions'; ?><?= $this->include('admin/_styles') ?><style>.delete-btn{padding:7px 10px;border:1px solid #f0cbd2;border-radius:7px;background:#fff6f7;color:#b8324b;font-size:12px;cursor:pointer}</style></head><body><div class="admin-app"><?php $username=session()->get('admin_username');$usertype=session()->get('admin_usertype'); ?><?= $this->include('admin/_sidebar') ?><main class="admin-main"><header class="admin-topbar"><div class="admin-top-title">Questions</div><div class="admin-search">⌕ <span>Search...</span><span style="margin-left:auto">⌘ K</span></div><div class="admin-pill">✦ AI insights</div><div style="font-size:20px;color:#778092">☼</div></header><div class="admin-content"><div class="admin-heading"><div><h1>Question library</h1><p>Build and manage the questions used in your applicant assessments.</p></div><a class="admin-btn" href="<?= site_url('admin/questions/new') ?>">＋ Create question</a></div><?php if (!$questions): ?><div class="admin-card admin-empty">No questions yet.</div><?php else: ?><div class="admin-table"><table><thead><tr><th>#</th><th>Question</th><th>Type</th><th>Points</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($questions as $index=>$question): ?><tr><td><?= $index+1 ?></td><td><strong><?= esc($question['prompt']) ?></strong><?php if ($question['hint']): ?><br><small style="color:#798196"><?= esc($question['hint']) ?></small><?php endif; ?><?php if ($question['options']): ?><details style="margin-top:8px;color:#69778d"><summary>View options</summary><ol><?php foreach($question['options'] as $option): ?><li><?= esc($option['text']) ?></li><?php endforeach; ?></ol></details><?php endif; ?></td><td><?= esc($question['type']) ?></td><td><?= esc($question['points']) ?></td><td><?= $question['is_active'] ? 'Active' : 'Inactive' ?></td><td><form method="post" action="<?= site_url('admin/questions/' . $question['id'] . '/delete') ?>" onsubmit="return confirm('Delete this question? This cannot be undone.');"><button class="delete-btn" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></main></div></body></html>
